<https://example.org/openevidence/questions/q_coronary_artery_disease_efficacy> a holon:ClinicalQuestionHolon ;
    oe:questionText "How effective is atorvastatin compared with other agents for Coronary Artery Disease?"^^xsd:string ;
    oe:answerText "To compare the long term efficacy and safety of rosuvastatin with atorvastatin treatment in adults with coronary artery disease. Randomised, open label, multicentre trial."^^xsd:string ;
    oe:belongsToSpecialty "Cardiology" ;
    holon:hasInteriorGraph <https://example.org/openevidence/questions/q_coronary_artery_disease_efficacy-int> ;
    holon:hasBoundaryGraph <https://example.org/openevidence/questions/q_coronary_artery_disease_efficacy-bou> ;
    holon:hasProjectionGraph <https://example.org/openevidence/questions/q_coronary_artery_disease_efficacy-pro> ;
    holon:hasContextGraph <https://example.org/openevidence/questions/q_coronary_artery_disease_efficacy-con> ;
    holon:evidenceQualityThreshold "0.50"^^xsd:decimal .

<https://example.org/openevidence/drugs/atorvastatin> oe:treats <https://example.org/openevidence/diseases/coronary_artery_disease> .
<https://example.org/openevidence/generated/ev_q_coronary_artery_disease_efficacy_0> a holon:EvidenceAssertion ;
    rdf:reifies <https://example.org/openevidence/generated/ev_q_coronary_artery_disease_efficacy_0-tt> ;
    holon:confidence "0.89"^^xsd:decimal ;
    holon:evidenceLevel "Level-1B" ;
    holon:assessedBy <https://example.org/openevidence/questions/openevidence_ai> ;
    holon:recordedOn "2026-12-31"^^xsd:date ;
    oe:cites <https://example.org/openevidence/sources/37852649> ;
    holon:inHolon <https://example.org/openevidence/questions/q_coronary_artery_disease_efficacy> ;
    oe:effectiveness "effective" .
<https://example.org/openevidence/generated/ev_q_coronary_artery_disease_efficacy_0-tt> rdf:subject <https://example.org/openevidence/drugs/atorvastatin> ;
    rdf:predicate oe:treats ;
    rdf:object <https://example.org/openevidence/diseases/coronary_artery_disease> .

<https://example.org/openevidence/drugs/atorvastatin> oe:treats <https://example.org/openevidence/diseases/hyperlipidemia> .   # ungrounded (naive)
